package com.srenterprises.entity; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="inventory_transactions") public class InventoryTransaction { @Id public UUID id=UUID.randomUUID(); @ManyToOne @JoinColumn(name="product_id") public Product product; @ManyToOne @JoinColumn(name="actor_id") public User actor; @Column(name="previous_quantity") public int previousQuantity; @Column(name="change_quantity") public int changeQuantity; @Column(name="new_quantity") public int newQuantity; public String reason; @Column(name="created_at") public Instant createdAt=Instant.now(); }
